-- « Courriers en masse » (LecteurCourriersEnMasse, EcrivainCourriersEnMasse), lot 10 du plan « RIG v3 100 % fonctionnel » (plan-676a4b19).
-- Identifiants 2 000 2xx, roles 2026CM202xx, audiences 2000201+. Joue avant PROC_GCONV.sql, PROC_DCA_RELANCE.sql et PROC_PREAUD.sql : les
-- tables qu'ils creent aussi le sont ici avec LEURS definitions (aux types de RIG_DEV), s'il est le premier. La fenetre de la recherche par
-- defaut vient de PROC_PREAUD.sql (INTERV_AUD_DATE_MIN_PREAUD 30, MAX -25 : du jour -30 au jour -25). Les files et imprimantes de la sortie :
-- celles de PROC_GESTLOT.sql (BANC9_COURRIERS active, BANC9_DIRECT directe, AMI_BANC9 d'Amitel), jouees avant les gestes.
-- Ce qui est retenu ou ecarte, et pourquoi : PROC_COURRIERM.attendu.
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CODE_AFFAIRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CODE_AFFAIRE varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_PRCLL') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_PRCLL int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_PREVE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_PREVE int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_AFFRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_AFFRE int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NUMERO_SOURCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NUMERO_SOURCE varchar(36) NULL;
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL, AUDNC_HEURE varchar(5) NULL);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_AUDIENCE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_AUDIENCE bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_CHAMBRE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_CHAMBRE varchar(5) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_SECTION') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_SECTION varchar(10) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ID_JUG') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ID_JUG int NULL;
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_NUM_ORDRE smallint NOT NULL,
        APPAF_ID_ADNC int NOT NULL);
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_NUM_APPEL') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_NUM_APPEL varchar(8) NULL;
IF OBJECT_ID(N'v2.CHAMBRE') IS NULL
    CREATE TABLE v2.CHAMBRE (R_CHAMBRE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_CHAMBRE_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_CHAMBRE_AVEC_COMPO bit NOT NULL DEFAULT (1));
IF OBJECT_ID(N'v2.SECTION') IS NULL
    CREATE TABLE v2.SECTION (R_SECTION_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_SECTION_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.JUGE') IS NULL
    CREATE TABLE v2.JUGE (JUG_ID_JUG int NOT NULL PRIMARY KEY, JUG_CIVILITE varchar(7) NOT NULL, JUG_NOM varchar(35) NOT NULL, JUG_PRENOM varchar(20) NULL);
IF OBJECT_ID(N'v2.CODE_AFFAIRE') IS NULL
    CREATE TABLE v2.CODE_AFFAIRE (R_CODEAFFAIR_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_CODEAFFAIR_LIBELLE_ECRAN varchar(100) NOT NULL,
        R_CODEAFFAIR_TYPE_NUM_ROLE varchar(5) NULL, R_CODEAFFAIR_TYPE_INSTANCE varchar(2) NOT NULL);
IF COL_LENGTH('v2.CODE_AFFAIRE', 'R_CODEAFFAIR_SYNONYME') IS NULL ALTER TABLE v2.CODE_AFFAIRE ADD R_CODEAFFAIR_SYNONYME varchar(16) NULL;
IF OBJECT_ID(N'v2.PROCEDURE_COLLECTIVE') IS NULL
    CREATE TABLE v2.PROCEDURE_COLLECTIVE (PRCLL_ID_PRCLL int NOT NULL PRIMARY KEY, PRCLL_ID_DSRCS int NULL);
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NUM_PC') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NUM_PC varchar(10) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NOM_AFFAIRE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NOM_AFFAIRE varchar(max) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NUMERO_SOURCE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_OUVERTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_OUVERTURE datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_SAUVEGARDE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_SAUVEGARDE datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_RETABL_PROF') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_RETABL_PROF datetime NULL;
IF OBJECT_ID(N'v2.PREVENTION') IS NULL
    CREATE TABLE v2.PREVENTION (PREVE_ID_PREVE int NOT NULL PRIMARY KEY, PREVE_NUM_PRV varchar(10) NULL, PREVE_NOM_AFFAIRE varchar(250) NULL);
IF OBJECT_ID(N'v2.MESURE') IS NULL
    CREATE TABLE v2.MESURE (MSINS_ID_MSINS int NOT NULL PRIMARY KEY, MSINS_ID_INSTN int NOT NULL, MSINS_ID_DCJDC int NOT NULL, MSINS_NUM_MESURE varchar(11) NULL);
-- La demande et la demande d'edition (definition de PROC_GCONV.sql ; les colonnes que l'ecrivain ecrit, s'il manque).
IF COL_LENGTH('v2.DEMANDE', 'DMND_EN_COURS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_EN_COURS bit NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM_UTILISATEUR') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM_UTILISATEUR varchar(255) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM varchar(255) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NUM_INDICATIF') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NUM_INDICATIF varchar(14) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_LES_NUMEROS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_LES_NUMEROS varchar(128) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_ID_AFFRE') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_ID_AFFRE int NULL;
IF OBJECT_ID(N'v2.DOSSIER_DEMANDE') IS NULL
    CREATE TABLE v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM int NOT NULL PRIMARY KEY, DSSDM_ID_DMND int NOT NULL,
        DSSDM_CODE_SEQUENCEUR varchar(20) NOT NULL, DSSDM_VALEUR_SEQUENCEUR varchar(100) NULL);
IF OBJECT_ID(N'v2.DEMANDE_EDITION') IS NULL
    CREATE TABLE v2.DEMANDE_EDITION (DMNED_ID_DMNED int NOT NULL PRIMARY KEY, DMNED_ID_DMND int NULL, DMNED_ID_DSRCS int NULL,
        DMNED_LOT varchar(255) NULL, DMNED_PHASE_TRAITEMENT varchar(10) NOT NULL, DMNED_DATE_PRE_EMISSION datetime NULL,
        DMNED_DESIGNATION_DESTINATAIRE varchar(255) NULL, DMNED_LIBELLE_DOCUMENT varchar(255) NOT NULL,
        DMNED_LIBELLE_ERREUR varchar(255) NULL, DMNED_DATE_CREATION datetime NULL, DMNED_ID_EMAIL_ENVOYE int NULL,
        DMNED_MODE_ENVOI int NULL);
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_ID_DMND') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_ID_DMND int NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_LOT') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_LOT varchar(255) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_IMPRIMANTE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_IMPRIMANTE varchar(255) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_CODE_ENTITE_SOURCE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_CODE_ENTITE_SOURCE varchar(16) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_VALEUR_ID_SOURCE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_VALEUR_ID_SOURCE varchar(40) NULL;
-- Les parametres d'edition (definition de PROC_DCA_RELANCE.sql).
IF OBJECT_ID(N'v2.PARAMETRE_EDITION') IS NULL
    CREATE TABLE v2.PARAMETRE_EDITION (PRMED_CODE varchar(40) NOT NULL PRIMARY KEY, PRMED_LIBELLE varchar(100) NOT NULL,
        PRMED_RECTO_VERSO bit NOT NULL DEFAULT 0, PRMED_AFFICHER_AVANT_IMPRESSION bit NOT NULL DEFAULT 0, PRMED_CODE_CFECP varchar(50) NULL,
        PRMED_LISTE varchar(4000) NOT NULL DEFAULT '', PRMED_CODE_ENTITE_SOURCE varchar(16) NULL, PRMED_CODE_PROCESSUS varchar(40) NULL,
        PRMED_CODE_MAQUETTE varchar(40) NULL, PRMED_TYPE_GENERATION varchar(15) NULL, PRMED_NOMBRE_EXEMPLAIRES int NOT NULL DEFAULT 1,
        PRMED_READ_ONLY bit NOT NULL DEFAULT 0, PRMED_NUM_GROUPE_IMPRESSION varchar(30) NULL, PRMED_TRIBUNAL_DIGITAL_NATURE_DOC varchar(50) NULL);
IF OBJECT_ID(N'v2.IMPRIMANTE_EDITION') IS NULL
    CREATE TABLE v2.IMPRIMANTE_EDITION (IMPED_NOM_LOGIQUE varchar(100) NOT NULL PRIMARY KEY, IMPED_NOM_PHYSIQUE varchar(255) NULL, IMPED_ONLY_AMITEL bit NULL);

-- Les compteurs DMD (s'il manque) et les fiches et secondes editions des volets Instances (EDIT_INS) et Procedures (EDIT_PC). FICHE_PC
-- manque : « Générer la fiche » d'une procedure est refuse. Une imprimante du greffe et une d'Amitel.
EXEC sp_executesql N'
IF NOT EXISTS (SELECT 1 FROM num.Compteur WHERE Type = ''DMD'')
    INSERT INTO num.Compteur (Type, Annee, Structure, CodageAnnee, Lettre, TailleChrono, Debut) VALUES (''DMD'', 2026, ''LAQC'', 2, ''D'', 5, 1);
INSERT INTO v2.PARAMETRE_EDITION (PRMED_CODE, PRMED_LIBELLE, PRMED_CODE_PROCESSUS, PRMED_TYPE_GENERATION) VALUES
    (''FICHE_INSTANCE'', ''Fiche instance'', ''EDIT_INS'', ''FUSION_RIG''),
    (''CONVOC20'', ''Convocation du banc lot 10'', ''EDIT_INS'', ''FUSION_RIG''),
    (''LETTREPC20'', ''Lettre procédure du banc lot 10'', ''EDIT_PC'', ''FUSION_RIG'');
INSERT INTO v2.IMPRIMANTE_EDITION (IMPED_NOM_LOGIQUE, IMPED_NOM_PHYSIQUE, IMPED_ONLY_AMITEL) VALUES
    (''Imprimante banc 10'', ''RL'', 0), (''Imprimante Amitel banc 10'', ''RL'', 1);
INSERT INTO v2.CODE_AFFAIRE (R_CODEAFFAIR_VALEUR, R_CODEAFFAIR_LIBELLE_ECRAN, R_CODEAFFAIR_TYPE_INSTANCE, R_CODEAFFAIR_SYNONYME) VALUES
    (''CM20'', ''Affaire du banc lot 10'', ''CX'', ''CM20'');';

-- Les audiences, en mai 1990 : hors de la fenetre par defaut (jour -30 a jour -25, PROC_PREAUD.sql) et de celles des autres ecrans
-- d'audience ; la recherche par leur date les choisit (PROC_COURRIERM.recherches). 2000201 et 2000204 le 14/05/1990 (une audience, un
-- cabinet), 2000202 le 15/05/1990, 2000203 le 13/05/1990.
EXEC sp_executesql N'
