    (2000203, ''1990-05-13'', ''09:00'', 1), (2000204, ''1990-05-14'', ''14:00'', 0);
IF COLUMNPROPERTY(OBJECT_ID(N''v2.PROCEDURE_COLLECTIVE''), ''PRCLL_ID_PRCLL'', ''IsIdentity'') = 1 SET IDENTITY_INSERT v2.PROCEDURE_COLLECTIVE ON;
