IF COLUMNPROPERTY(OBJECT_ID(N''v2.PROCEDURE_COLLECTIVE''), ''PRCLL_ID_PRCLL'', ''IsIdentity'') = 1 SET IDENTITY_INSERT v2.PROCEDURE_COLLECTIVE OFF;
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_CODE_AFFAIRE, INSTN_ID_PRCLL, INSTN_NUMERO_SOURCE) VALUES
    (2000201, ''2026CM20201'', ''COURRIER A'', ''CM20'', NULL, ''00000000-0000-0000-0000-000002000201''),
    (2000202, ''2026CM20202'', ''COURRIER B'', NULL, 2000201, NULL),
    (2000203, ''2026CM20203'', ''COURRIER C'', NULL, NULL, NULL),
    (2000204, ''2026CM20204'', ''COURRIER D'', NULL, NULL, NULL),
    (2000205, ''2026CM20205'', ''COURRIER E'', NULL, NULL, NULL);
INSERT INTO v2.APPEL_AFFAIRE (APPAF_ID_APPAF, APPAF_ID_INSTN, APPAF_NUM_ORDRE, APPAF_ID_ADNC, APPAF_NUM_APPEL) VALUES
